    // ensures: result.len() == 2 && result[0] == 'N' && result[1] == 'O' if not all characters are in the same set
    // ensures: result.len() == 2 && result[0] == 'Y' && result[1] == 'E' if all characters are in the same set
    if word.is_empty() {
        return "NO".chars().collect();
    }

    // Determine the set of the first character
    let is_in_set_a = set_a.contains(&word[0]);
    let is_in_set_b = set_b.contains(&word[0]);

